import { useState } from 'react';
import './FormValidation.css';


function FormValidation(){

    

    const [formData, setFormData] = useState({
        name:'',
        email:'',
        mobile: ''
    })

    const validatorMethods = {
        name: (val) => {
            if(/[0-9]/.test(val)){
                console.log('Invalid Input');
            }
        }
    }

// this is how i am going to handle all the keys
    const inputChangeHandler=(key)=>{  // key passed
        return (e)=>{ // whatever change is happening
            const val = e.target.value
setFormData((data)=>{  // updating the state
    return {
        ...data,
        [key] : val
    }
})
validatorMethods[key](val)
        }
    }


    return<>
    <div className="form-container" >
        <form action='#' method="POST" onSubmit={(e)=>{
            e.preventDefault();
            console.log(formData);
            setFormData({
                name:'',
                email: "",
                mobile:""
            })
        }} >
            <h2>Fill The Details</h2>

            <div className="field-container" >
            <label>Name: </label>
            <input type="text" placeholder="type your Name"
            // onChange={(e)=>{setFormData({
            //     ...formData,
            //     name: e.target.value
            // })}}
            onChange={inputChangeHandler('name')} 
            value={formData.name}
            required />
            </div>

            <div className="field-container" >
            <label>Email: </label>
            <input type="email" placeholder="type your Email" 
            // onChange={(e)=>{
            //     setFormData({
            //         ...formData,
            //         email: e.target.value
            //     })
            // }}
            onChange={inputChangeHandler('email')}
            value={formData.email}
            required />
            </div>

            <div className="field-container" >
            <label>Mobile No: </label>
            <input type="number" placeholder="type your Number " 
            // onChange={(e)=>{
            //     setFormData({
            //         ...formData,
            //         mobile: e.target.value
            //     })
            // }}
            onChange={inputChangeHandler('mobile')}
            value={formData.mobile}
            required />
            </div>

            <div>
            <button type='submit' >Submit</button>
            </div>

        </form>
    </div>
    </>
    
}

export default FormValidation
